    </v-dialog>
</template>
<script setup>
import { inject, onBeforeMount, ref, watch, computed, mergeProps, toRaw } from 'vue';
import { useToken } from '@/composables/tokens';
import { useDisplay } from 'vuetify'
import { useAppTheme } from '@/composables/useAppTheme'
import { openOidcAuthUrl, exchangeRefreshToken} from '@/modules/oidc'
const { isDark, toggleTheme } = useAppTheme()
const { mobile } = useDisplay()
const branch = __SV_BRANCH__;
const commit = __SV_COMMIT_HASH__;
const commit_short = __SV_COMMIT_HASH_SHORT__;
const date = __SV_COMMIT_DATE__;
const branch_build = __BUILD_BRANCH__;
const commit_build = __BUILD_COMMIT_HASH__;
const commit_short_build = __BUILD_COMMIT_HASH_SHORT__;
const date_build = __BUILD_COMMIT_DATE__;
const build_date = __BUILD_DATE__;
const link = `https://hub.psychoinformatics.de/orinoco/shacl-vue/src/commit/${commit}`;

const props = defineProps({
    logo: String,
});

const { token, setToken, clearToken, getTokenDetails, getTokenValidity} = useToken();
const submitFn = inject('submitFn');
const canSubmit = inject('canSubmit');
const nodesToSubmit = inject('nodesToSubmit');
const formOpen = inject('formOpen');
const configVarsMain = inject('configVarsMain');
const config = inject('config');
const http401response = inject('http401response');
const allPrefixes = inject('allPrefixes');
const tokenWarning = inject('tokenWarning');
const tokenWarningPulse = ref(false);
const submitWarning = inject('submitWarning');
const submitWarningPulse = ref(false);
const visible = ref(false);
const tokenDialog = ref(false);
const tokenExists = ref(false);
const tokenval = ref('');
const tokenForm = ref(null);
const rules = [
    (value) => {
        if (value) return true;
        return 'A token is required';
    },
];
const customError = ref('')
const emit = defineEmits(['tokenDialogOpened', 'reselectType'])
const settingsDialog = ref(false);
const tab = ref('info');
const filterCurieText = ref('');
const orderTopDown = ref(true);
const orderIcon = ref('mdi-arrow-down-thick');

const filterConfigText = ref('');
const appVariant = import.meta.env.VITE_SHACLVUE_VARIANT;
const appName = ref('');
const userIcon = ref('mdi-account');

onBeforeMount(async () => {
    const tokenDeets = getTokenDetails()
    const tokenValid = getTokenValidity()
    if (tokenDeets.tokenType == 'oidc') {
        if (tokenValid) userIcon.value = 'mdi-account-check';
        else {
            try {
                const ts = await refreshOidcLogin()
                console.log(ts)
                setToken(
                    ts.access_token,
                    'oidc',
                    ts.expires_in,
                    ts.refresh_token
                )
                userIcon.value = 'mdi-account-check';
                emit('reselectType')
            }
            catch (error) {
                console.log(error)
            }
            
        }
    }

    if (token.value !== null && token.value !== 'null') {
        tokenExists.value = true;
        tokenval.value = token.value;
    }
    
    let variantAppName = `app_name_${appVariant}`;
    appName.value = config.value[variantAppName] || configVarsMain.appName; 
});

const filteredConfigOptions = computed(() => {
    let txt = filterConfigText.value.toLowerCase().trim();
    return Object.keys(config.value).filter((item) => {
        if (txt.length == 0) return true;
        return item.toLowerCase().trim().includes(txt);
    })
});

const filteredCURIEs = computed(() => {
    let txt = filterCurieText.value.toLowerCase().trim();
    return sortItems(
        Object.keys(allPrefixes).filter((item) => {
            if (txt.length == 0) return true;
            return item.toLowerCase().trim().includes(txt);
        }),
        orderTopDown.value
    )
});

function sortItems(arr, orderVal) {
    const c = orderVal ? 1 : -1;
    return arr.sort((a, b) => {
        return c * a.localeCompare(b);
    })
}

function toggleOrder() {
    orderTopDown.value = !orderTopDown.value;
    if (orderTopDown.value) {
        orderIcon.value = 'mdi-arrow-down-thick';
    } else {
        orderIcon.value = 'mdi-arrow-up-thick';
    }
}

function clearField(mode) {
    if (mode == 'configText') {
        filterConfigText.value = '';
    } else {
        filterCurieText.value = '';
    }
}

function goToHome() {
    window.location.href = window.location.pathname;
}

function cancel() {
    tokenDialog.value = false;
}

function settingsFn() {
    if (token.value !== null && token.value !== 'null') {
        tokenExists.value = true;
        tokenval.value = token.value;
    }
    tab.value = 'info';
    settingsDialog.value = true;
}

function reset() {
    tokenval.value = '';
    http401response.value = false;
    customError.value = ''
    clearToken();
    emit('reselectType')
}

watch(
    http401response,
    (newValue) => {
        if (newValue) {
            forceError()
            tokenDialog.value = true;
            tokenWarning.value = true;
            // The following was missing previously, and should actually be included for
            // the intended functionality. However, this will cause the token dialog to
            // appear (if an incorrect token is set) every single time a new class is selected
            // which IMO is too intrusive. Leaving it out until a better idea comes along.
            // http401response.value = false;

            userIcon.value = 'mdi-account';
        }
    },
    { immediate: true }
);

watch(
    tokenDialog,
    (newValue) => {
        if (newValue) {
            emit('tokenDialogOpened')
        }
    },
    { immediate: true }
);

watch(
    tokenWarning,
    (newValue) => {
        if (newValue) {
            tokenWarningPulse.value = true
            setTimeout(() => {
                tokenWarningPulse.value = false
            }, 4000)
            tokenWarning.value = false;
        }
    },
    { immediate: true }
);

watch(
    submitWarning,
    (newValue) => {
        if (newValue) {
            if (
                configVarsMain.reviewBundleMode === 'patch-download' ||
                (token.value !== null && token.value !== 'null')
            ) {
                submitWarningPulse.value = true
                setTimeout(() => {
                    submitWarningPulse.value = false
                }, 4000)
            } else {
                tokenWarning.value = true;
                tokenDialog.value = true;
                userIcon.value = 'mdi-account';
            }
            submitWarning.value = false;
        }
    },
    { immediate: true }
);

function forceError() {
    customError.value = "Invalid token. Please re-enter your token and click Save, or alternatively clear the token by clicking Reset and then Cancel"
}

async function save() {

    const { valid } = await tokenForm.value.validate();
    if (!valid) {
        console.log('invalid entry');
        return;
    }

    http401response.value = false;
    customError.value = ''
    tokenDialog.value = false;
    if (tokenval.value != token.value) {
        setToken(tokenval.value, 'manual');
        emit('reselectType')
    }
    if (nodesToSubmit.value.length) {
        submitWarning.value = true;
    }
    settingsDialog.value = false;
}

async function refreshToken() {
    const tokens = await refreshOidcLogin();
    if (tokens) {
        setToken(
            tokens.access_token,
            'oidc',
            tokens.expires_in,
            tokens.refresh_token
        )
        if (settingsDialog.value == true) settingsDialog.value = false
        emit('reselectType')
    }
}

async function refreshOidcLogin() {
    const tokenDeets = getTokenDetails()
    console.log('refreshing token with', tokenDeets.refreshToken)
    const tokens = await exchangeRefreshToken(tokenDeets.refreshToken, toRaw(configVarsMain.oidc[0]))
    return tokens
}

function loginToOidcServer(config, source = 'header') {
    const el = (event) => {
        if (event.origin !== window.location.origin)
            return;
        if (event.source === window)
            return;
        if (!event.data?.type.includes("oidc-login"))
            return;
        setToken(
            event.data.payload.accessToken,
            'oidc',
            event.data.payload.expiresIn,
            event.data.payload.refreshToken,
        )
        userIcon.value = 'mdi-account-check';
        tokenExists.value = true;
        tokenval.value = token.value;
        if (source == 'dialog') {
            http401response.value = false;
            customError.value = ''
            tokenDialog.value = false;
            emit('reselectType')
        }
        if (source == 'token-tab') {
            settingsDialog.value = false;
            emit('reselectType')
        }
        window.removeEventListener("message", el);
    }
    window.addEventListener("message", el);
    openOidcAuthUrl(config)
}


</script>

