<template>
    <v-input
        v-model="internalValue"
        :rules="rules"
        ref="fieldRef"
        :id="inputId"
        hide-details="auto"
    >
        <v-container fluid class="pa-0 ma-0">
            <v-row justify="start" no-gutters class="ma-0 pa-0">
                <v-checkbox
                    class="ma-0 pa-0 scaled-comp"
                    v-model="enterCURIE"
                    density="compact"
                    label="CURIE"
                    hide-details="auto"
                ></v-checkbox>
            </v-row>
            <v-row v-if="!enterCURIE" justify="start" no-gutters>
                <v-text-field
                    v-model="subValues.uri_text"
                    label="add URI text"
                    density="compact"
                    variant="outlined"
                    hide-details="auto"
                ></v-text-field>
            </v-row>
            <v-row v-else justify="start" no-gutters>
                <v-col cols="5">
                    <v-select
                        label="prefix"
                        v-model="subValues.uri_prefix"
                        :items="prefixOptions"
                        density="compact"
                        variant="outlined"
                        style="margin-bottom: 0; padding-bottom: 0"
                        hide-details="auto"
                    ></v-select>
                </v-col>
                <v-col cols="7">
                    <v-text-field
                        v-model="subValues.uri_path"
                        density="compact"
                        style="margin-bottom: 0; padding-bottom: 0"
                        variant="outlined"
                        label="add text"
                        validate-on="lazy input"
                        hide-details="auto"
                    >
                    </v-text-field>
                </v-col>
            </v-row>
        </v-container>
    </v-input>
</template>

<script setup>
import { inject, computed, ref, watch, onMounted, onBeforeMount} from 'vue';
import { useRules } from '@/composables/rules';
import { isObject, isCURIE, toCURIE, toIRI} from '@/modules/utils';
import { useRegisterRef } from '@/composables/refregister';
import { useBaseInput } from '@/composables/base';
import { useCompConfig } from '@/composables/useCompConfig';

const props = defineProps({
    modelValue: String,
    property_shape: Object,
    node_uid: String,
    triple_uid: String,
    triple_idx: Number,
});
const { rules } = useRules(props.property_shape);
rules.value.push((value) => {
    const uriRegex =
        /^([a-zA-Z][a-zA-Z0-9+-.]*):(?:\/\/((?:[a-zA-Z0-9\-._~%!$&'()*+,;=]+@)?(?:\[(?:[A-Fa-f0-9:.]+)\]|(?:[a-zA-Z0-9\-._~%]+))(?:\:[0-9]+)?)?)?((?:\/[a-zA-Z0-9\-._~%!$&'()*+,;=:@]*)*)(?:\?[a-zA-Z0-9\-._~%!$&'()*+,;=:@/?]*)?(?:\#[a-zA-Z0-9\-._~%!$&'()*+,;=:@/?]*)?$/;
    if (!value) return true;
    if (uriRegex.test(value)) return true;
    return 'This is not a valid URI of type XSD:anyURI';
});
const inputId = `input-${Date.now()}`;
const { fieldRef } = useRegisterRef(inputId, props);

const allPrefixes = inject('allPrefixes');
const configVarsMain = inject('configVarsMain');
const enterCURIE = ref(true);

const emit = defineEmits(['update:modelValue']);
const { subValues, internalValue } = useBaseInput(
    props,
    emit,
    valueParser,
    valueCombiner
);
const {componentName, componentConfig} = useCompConfig(configVarsMain)

// ----------------- //
// Lifecycle methods //
// ----------------- //

onBeforeMount(() => {
    if (componentConfig && isObject(componentConfig) && Object.keys(componentConfig).includes(props.triple_uid)) {
        enterCURIE.value = componentConfig[props.triple_uid];
    } else if (componentConfig && componentConfig.default ) {
        enterCURIE.value = componentConfig.default == 'curie';
    } else {
        enterCURIE.value = true;
    }

    if (props.modelValue) {
        var curieparts = toCURIE(props.modelValue, allPrefixes, 'parts');
        var iC = isCURIE(props.modelValue, allPrefixes, true);
        if (iC) {
            enterCURIE.value = true;
            subValues.value.uri_prefix = iC.prefix;
            subValues.value.uri_path = iC.reference;
            subValues.value.uri_text = toIRI(`${iC.prefix}:${iC.reference}`, allPrefixes)

        } else {
            enterCURIE.value = false;
            subValues.value.uri_text = props.modelValue;
        }
    }
});

// ------------------- //
// Computed properties //
// ------------------- //

const prefixOptions = computed(() => {
    var prefixes = [];
    for (const [k, v] of Object.entries(allPrefixes)) {
        prefixes.push({
            title: k,
            value: k,
            props: { subtitle: v },
        });
    }
    return prefixes.sort((a, b) => a.title.localeCompare(b.title));
});

// --------- //
// Functions //
// --------- //

function valueParser(value) {
    // Parsing internalValue into ref values for separate subcomponent(s)

    // internalValue is a URI
    // - if internalValue is null, set all to null or empty strings
    // - for the text field: set directly from internalValue
    // - for the curie:
    //   - call toCurie in order to split it up into prefix and path
    //   - if toCurie not possible (i.e. unknown prefix), don't set the prefix nor path (or set to null or empty string?)
    // whether the switch is set to uri or curie is not important here
    var URItext, URIprefix, URIpath;
    if (!value) {
        URItext = '';
        URIprefix = null;
        URIpath = '';
    } else {
        URItext = value;
        var curieparts = toCURIE(value, allPrefixes, 'parts');
        if (isObject(curieparts)) {
            URIprefix = curieparts.prefix;
            URIpath = curieparts.property;
        } else {
            URIprefix = null;
            URIpath = '';
            enterCURIE.value = false;
        }
    }
    return {
        uri_text: URItext,
        uri_prefix: URIprefix,
        uri_path: URIpath,
    };
}

function valueCombiner(values) {
    // Determine internalValue (a URI) from subvalues/subcomponents

    // if the switch is set to URI:
    // - return subValues.uri_text
    // if switch set to CURIE (default):
    // - if prefix not selected
    if (!enterCURIE.value) {
        return values.uri_text ?? '';
    } else {
        if (values.uri_prefix !== null) {
            return `${allPrefixes[values.uri_prefix] ?? ''}${values.uri_path ?? ''}`;
        } else {
            return `${values.uri_path ?? ''}`;
        }
    }
}
</script>

<script>
import { SHACL, XSD } from '../modules/namespaces';
export const matchingLogic = (shape) => {
    // sh:nodeKind exists
    if (shape.hasOwnProperty(SHACL.nodeKind.value)) {
        // sh:nodeKind == sh:Literal
        if (shape[SHACL.nodeKind.value] == SHACL.Literal.value) {
            // sh:datatype exists
            if (shape.hasOwnProperty(SHACL.datatype.value)) {
                // sh:datatype == xsd:anyURI
                return shape[SHACL.datatype.value] == XSD.anyURI.value;
            }
        }
        // sh:nodeKind == sh:IRI and sh:datatype does not exists
        if ((shape[SHACL.nodeKind.value] == SHACL.IRI.value) &&
            !shape.hasOwnProperty(SHACL.datatype.value)
        ) {
            return true
        }
    }
    // if sh:nodeKind does not exist, but datatype still exists
    if (shape.hasOwnProperty(SHACL.datatype.value)) {
        // sh:datatype == xsd:anyURI
        return shape[SHACL.datatype.value] == XSD.anyURI.value;
    }
    return false;
};
</script>

<style scoped>
.scaled-comp {
    margin-top: 0;
    margin-left: 0.5em;
    padding-top: 0;
    transform: scale(0.85);
    transform-origin: top left;
}
</style>
