<template>
    <v-sheet ref="mainSheet" class="pa-4" :class="mobile ? 'scaled-sheet-mobile' : 'scaled-sheet'" :border="mobile?false:true" :rounded="mobile?false:true" >
        <div style="display: flex; position: relative">
            <h3>
                <v-tooltip :text="toCURIE(localShapeIri, allPrefixes)" location="bottom">
                    <template v-slot:activator="{ props }">
                        <v-icon v-bind="props">{{ getClassIcon(localShapeIri, allPrefixes) }}</v-icon>
                    </template>
                </v-tooltip>&nbsp;&nbsp;
                {{ getDisplayName(localShapeIri, configVarsMain, allPrefixes, shape_obj) }}
            </h3>

            <div style="display: flex; margin-left: auto">
                <span v-if="mobile">
                    <v-btn
                        @click="cancelForm()"
                        style="margin-left: auto; margin-right: 1em"
                        icon="mdi-close-box"
                        size="small"
                    ></v-btn>
                    <v-btn
                        @click="resetForm()"
                        style="margin-right: 1em"
                        icon="mdi-undo"
                        size="small"
                    ></v-btn>
                    <v-btn
                        type="submit"
                        @click="saveForm()"
                        icon="mdi-content-save"
                        size="small"
                    ></v-btn>
                </span>
                <span v-else>
                    <v-btn
                        text="Cancel"
                        @click="cancelForm()"
                        style="margin-left: auto; margin-right: 1em"
                        prepend-icon="mdi-close-box"
                    ></v-btn>
                    <v-btn
                        text="Reset"
                        @click="resetForm()"
                        style="margin-right: 1em"
                        prepend-icon="mdi-undo"
                    ></v-btn>
                    <v-btn
                        text="Save"
                        type="submit"
                        @click="saveForm()"
                        prepend-icon="mdi-content-save"
                    ></v-btn>
                </span>
            </div>

            <div
                v-if="validationErrors.length"
                class="position-sticky top-4"
                style="margin-left: 1em"
            >
                <v-menu location="end">
                    <template v-slot:activator="{ props }">
                        <v-btn
                            color="warning"
                            v-bind="props"
                            density="compact"
                            icon="mdi-alert-circle-outline"
                        ></v-btn>
                    </template>
                    <v-list>
                        <v-list-item
                            v-for="e of validationErrors"
                            @click="goToError(e)"
                        >
                            <v-list-item-title>
                                <em>{{ e.name }}</em></v-list-item-title
                            >
                            <v-list-item-subtitle>{{
                                e.message
                            }}</v-list-item-subtitle>
                        </v-list-item>
                    </v-list>
                </v-menu>
            </div>
        </div>

        <span v-if="localNodeIdx && localShapeIri">
            <v-form
                ref="form"
                v-model="formValid"
                validate-on="lazy input"
                @submit.prevent="saveForm()"
            >
                <br />
                <p v-html="formattedDescription" class="quote-description"></p>
                <div style="margin-top: 0.3em;"></div>
                <span v-if="fieldNotes">
                    <span v-for="(note, i) in fieldNotes">
                        <em v-if="i == 0"><p v-html="addCodeTagsToText(note, 'Notes: <br/>* ')" class="quote-description"></p></em>
                        <em v-else><p v-html="addCodeTagsToText(note, '* ')" class="quote-description"></p></em>
                    </span>
                </span>
                <br />
                <NodeShapeEditor
                    :key="localShapeIri"
                    :shape_iri="localShapeIri"
                    :node_idx="localNodeIdx"
                />
                <div class="top-1">
                    <v-switch
                        v-model="show_all_fields"
                        :label="`All fields`"
                        hide-details
                        color="primary"
                    ></v-switch>
                </div>
                <div style="display: flex">
                    <v-tooltip text="Scroll to top" location="top">
                        <template v-slot:activator="{ props }">
                            <v-btn
                                icon="mdi-arrow-up-bold"
                                @click="scrollToTop()"
                                style="margin-left: auto"
                                v-bind="props"
                            ></v-btn>
                        </template>
                    </v-tooltip>
                </div>
            </v-form>
        </span>
    </v-sheet>
</template>

<script setup>
import {
    ref,
    onMounted,
    onBeforeMount,
    onBeforeUnmount,
    provide,
    inject,
    reactive,
    computed,
    toRaw,
    nextTick,
    watch,
} from 'vue';
import { SHACL, RDFS } from '@/modules/namespaces';
import {
    addCodeTagsToText,
    getDisplayName,
    findObjectByKey,
    getNotes,
    toCURIE
} from '@/modules/utils';
import { useDisplay } from 'vuetify'
const { mobile } = useDisplay()

// ----- //
// Props //
// ----- //

const props = defineProps({
    shape_iri: String,
    node_idx: String,
    onSaveEvent: {
        type: Function,
        default: undefined,
    },
});

// ---- //
// Data //
// ---- //
const mainSheet = ref(null)
const localShapeIri = ref(props.shape_iri);
const localNodeIdx = ref(props.node_idx);
const shapesDS = inject('shapesDS');
const rdfDS = inject('rdfDS');
const formData = inject('formData');
const config = inject('config');
const ID_IRI = inject('ID_IRI');
const allPrefixes = inject('allPrefixes');
const editMode = inject('editMode');
const removeForm = inject('removeForm');
const savedNodes = inject('savedNodes');
const nodesToSubmit = inject('nodesToSubmit');
const getClassIcon = inject('getClassIcon');
const shape_obj = shapesDS.data.nodeShapes[localShapeIri.value];
const form = ref(null);
const formValid = ref(null);
const fieldMap = reactive({}); // Maps element IDs to human-readable labels
const validationErrors = ref([]);
const cancelButtonPressed = ref(false);
const saveButtonPressed = ref(false);
const configVarsMain = inject('configVarsMain');
const openForms = inject('openForms')
const currentForm = ref(null);
function registerRef(id, fieldData) {
    fieldMap[id] = fieldData;
}
function unregisterRef(id) {
    delete fieldMap[id];
}
const submitWarning = inject('submitWarning');
provide('registerRef', registerRef);
provide('unregisterRef', unregisterRef);
provide('cancelButtonPressed', cancelButtonPressed);
provide('saveButtonPressed', saveButtonPressed);
// Storage of save/cancel handlers of all properties of the form
const handlers = ref({
    'save': [],
    'cancel': [],
    'reopen': [],
});
function registerHandler(handle, fn) {
    handlers.value[handle].push(fn);
}
provide('registerHandler', registerHandler);
const show_all_fields = ref(false);
provide('show_all_fields', show_all_fields);
const fieldNotes = ref([]);
const recordItemsAll = inject('recordItemsAll');


// ----------------- //
// Lifecycle methods //
// ----------------- //

onBeforeMount(() => {
    console.log(`the FormEditor component is about to be mounted.`);
    formData.addSubject(localShapeIri.value, localNodeIdx.value);
    currentForm.value = openForms.find((f) => {
        f.shapeIRI == props.shape_iri && f.nodeIDX == props.node_idx
    });
    if (!currentForm.value) {
        currentForm.value = openForms.at(-1);
    }
    if (config.value.hasOwnProperty('show_all_fields')) {
        if (
            typeof config.value.show_all_fields == 'boolean' &&
            config.value.show_all_fields
        ) {
            show_all_fields.value = true;
        }
    }
    fieldNotes.value = getNotes(shape_obj);
});

onBeforeUnmount(() => {
    console.log(`Running onBeforeUnmount for formeditor: ${props.shape_iri}`);
    localShapeIri.value = null;
});

onMounted(() => {
    console.log(`the FormEditor component is now mounted: ${localShapeIri.value} - ${localNodeIdx.value}`);
});

// Watch for change in openForm length, specifically if a form is closed leading to reopening
// of a previous form; if this is true, run all registered 'reopen' handlers
watch(
    () => openForms.length,
    (newLen, oldLen) => {
        // ignore if a new form is opened
        if (newLen >= oldLen) return;
        let newOpenForm = openForms.at(-1);
        // run reopen handlers from the currently open form
        if (currentForm.value.shape_iri == newOpenForm.shape_iri && currentForm.value.node_idx == newOpenForm.node_idx) {
            for (const handler of handlers.value['reopen']) {
                handler();
            }
        }
    }
);

// ------------------- //
// Computed properties //
// ------------------- //
const formattedDescription = computed(() => {
    // For the class description, use a regular expression to replace text between backticks with <code> tags
    if (shape_obj && (shape_obj[RDFS.comment.value] || shape_obj[SHACL.description.value])) {
        return addCodeTagsToText(shape_obj[RDFS.comment.value] || shape_obj[SHACL.description.value]);
    } else {
        return '-';
    }
});

// --------- //
// Functions //
// --------- //

async function saveForm() {
    try {
        validationErrors.value = [];
        // Await the validation result
        const validationResult = await form.value.validate();
        if (validationResult.valid) {
            // If the form is valid, proceed with form submission
            // run save handlers
            for (const handler of handlers.value['save']) {
                handler();
            }
            // Here, we distinguish between saving a newly created and completed form,
            // and saving a form that is being edited and was previously saved. The former
            // follows a standard workflow in one direction: from formData to graphData;
            // the latter requires tasks to be completed on both ends, specifically: deleting
            // existing quads from graphData before creating the updated quads from formData.
            // One thing that needs to be tracked externally is whether the value of ID_IRI
            // property of the node (if it has one) has changed, i.e. whether the user edited
            // the node's ID, because this will require additional steps. Below, we pass the
            // editMode variable to `save_node` in order to know whether this was a form for
            // a newly created node or for a pre-existing one, but the pre-edit and post-edit
            // values of the ID_IRI field is only known within the corresponding `PropertyShapeEditor`
            // component, so this needs to be indexed or passed or provided somehow to the
            // `save_node` function. TODO.
            // Update: Rethinking this, the pre-edit value of the ID_IRI field
            // would be the same as the localNodeIdx.value (IRI of blankNode or namedNode) and the
            // post-edit value would be in formData, so we have everything we need in `save_node`.

            // Note the "additional steps" needed when the node IRI is altered is to RE-reference
            // existing triples in the graph that has the current node as object. This is only
            // necessary for namedNodes where the IRI changed. The process will need to be:
            // - only do the following if the node is a namedNode and if the IRI changed during editing
            // - find all triples with the node IRI as object -> oldTriples
            // - for each triple in oldTriples: create a new one with same subject and predicate
            //   and with new IRI as object, then delete the old triple
            console.log('going to save form now');
            saveButtonPressed.value = true;
            const reactiveCloneFunc = (data) => {
                console.log('using reactiveCloneFunc with data:');
                console.log(toRaw(data));
                return structuredClone(toRaw(data));
            };
            var saved_node = formData.saveNode(
                localShapeIri.value,
                localNodeIdx.value,
                shapesDS,
                rdfDS,
                editMode.value,
                reactiveCloneFunc
            );
            // saved_node = {
            //   nodeshape_iri: "",
            //   node_iri: ""
            // }
            savedNodes.value.push(saved_node);
            // Remove the node data from formData, because:
            // - submission happens from graph store
            // - formData needed for editing the node will just be generated on-demand in future
            if (currentForm.value.removeNode === true || currentForm.value.removeNode === 'onSave') {
                console.log(`Finished saving; Removing current node: ${saved_node.nodeshape_iri} - ${saved_node.node_iri}`);
                formData.removeSubject(saved_node.nodeshape_iri, saved_node.node_iri);
            }
            // In order for the node to be submitted, it should have a PID
            // (because blank nodes aren't submitted as such, they are resolved
            // into named nodes), and it should not already be in nodesToSubmit.value.
            // Check if node has PID:
            // if the nodeshape does NOT have a propertyshape with sh:path being equal to ID_IRI,
            // it means the class's records will be blank nodes these should not be submitted
            var nodeShape = shapesDS.data.nodeShapes[saved_node.nodeshape_iri];
            var ps = nodeShape.properties.find(
                (prop) => prop[SHACL.path.value] == ID_IRI.value
            );
            if (
                ps &&
                !findObjectByKey(
                    nodesToSubmit.value,
                    'node_iri',
                    saved_node.node_iri
                )
            ) {
                nodesToSubmit.value.push(saved_node);
                // we also need to add/update the record to the global list
                if (recordItemsAll[saved_node.node_iri]) {
                    recordItemsAll[saved_node.node_iri].status = null;
                }
                rdfDS.emitAddedRecords([saved_node.node_iri])
            }
            removeForm(saved_node);
            if (nodesToSubmit.value.length) {
                submitWarning.value = true;
            }
            if (typeof props.onSaveEvent === 'function') {
                props.onSaveEvent(saved_node);
            }
        } else {
            console.log('Still some validation errors...');
            validationResult.errors.forEach((error) => {
                const id = error.id;
                const fieldData = fieldMap[id];
                if (fieldData) {
                    validationErrors.value.push({
                        name: fieldData.name,
                        message: error.errorMessages.join(', '),
                        element_id: error.id,
                    });
                }
            });
        }
    } catch (error) {
        console.error('Validation failed:', error);
    }
}

function resetForm() {
    formData.clearSubject(localShapeIri.value, localNodeIdx.value);
    form.value.resetValidation();
    validationErrors.value = [];
}

function cancelForm() {
    cancelButtonPressed.value = true;
    // run cancel handlers
    for (const handler of handlers.value['cancel']) {
        handler();
    }
    console.log('Cancelling form from FormEditor');
    console.log(`Removing current node: ${localShapeIri.value} - ${localNodeIdx.value}`);
    // Always remove node from formData...
    // - if cancelling from new item creation, no quads are in graph store
    // - if cancelling from item editing, true state quads are in graph store
    // ... unless explicitly told not to remove form, via openForms removeNode argument:
    if (currentForm.value.removeNode === true || currentForm.value.removeNode === 'onCancel') {
        formData.removeSubject(localShapeIri.value, localNodeIdx.value);
    }
    removeForm(null);
}

function scrollAllParentsToTop(el) {
  while (el) {
    if (el.scrollTop > 0) {
      el.scrollTo({ top: 0, behavior: 'smooth' });
    }
    el = el.parentElement;
  }
}

function scrollToTop() {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    nextTick(() => {
        const baseEl = mainSheet.value?.$el || mainSheet.value;
        if (baseEl) scrollAllParentsToTop(baseEl);
    });
}

function goToError(e) {
    console.log(e);
    var el = document.getElementById(e.element_id);
    if (el) {
        el.scrollIntoView({
            behavior: 'smooth',
        });
    } else {
        el = document.getElementById(e.element_id + '-messages');
        if (el) {
            el.scrollIntoView({
                behavior: 'smooth',
            });
        }
    }
}
</script>

<style scoped>
.scaled-sheet {
    transform: scale(0.9);
    transform-origin: top;
}
.scaled-sheet-mobile {
    transform: scale(0.75);
    transform-origin: top left;
    width: 130%;
}
.quote-description {
    border-left: 3px solid rgb(154, 153, 153);
    padding-left: 1em;
}
</style>
